let size=90;
function renderProducts(){
 const index=size===90?0:1;
 document.getElementById('products').innerHTML=products.map(p=>{
  const photo=p.unconfirmed?p.photos[0]:p.photos[index];
  const alt=p.unconfirmed?'Imagem de lançamento da pipoca Ovomaltine divulgada pela Dolce Vita no Instagram':`Pipoca Gourmet ${p.name}, embalagem de ${size} g, foto oficial do iFood`;
  const details=p.unconfirmed?`<div class="product-foot unconfirmed"><div><strong>Consulte o preço</strong><small>Preço e tamanhos a confirmar com a loja.</small></div></div><div class="product-actions"><a class="text-link" href="https://ig.me/m/dolcevitabyvalentina" target="_blank" rel="noopener noreferrer">Consultar no Direct ↗</a><a class="text-link catalog-link" href="${FOOD}" target="_blank" rel="noopener noreferrer">Ver cardápio no iFood ↗</a></div><p class="availability-note">Consulte a loja sobre a disponibilidade no iFood.</p>`:`<div class="product-foot"><div><strong>R$ ${size===90?'24,99':'34,99'}</strong><small>Embalagem de ${size} g</small></div><a href="${FOOD}?prato=${p.ids[index]}" target="_blank" rel="noopener noreferrer" aria-label="Pedir pipoca ${p.name}, ${size} gramas, no iFood">↗</a></div>`;
  return `<article class="product-card ${p.unconfirmed?'new-flavor':''}"><div class="product-photo"><img src="assets/${photo}" alt="${alt}" loading="lazy">${p.unconfirmed?'<span class="new-badge">NOVO SABOR</span>':''}</div><div class="product-info"><h3>${p.name}</h3><p>${p.description}</p>${details}</div></article>`;
 }).join('');
}
document.querySelectorAll('[data-size]').forEach(button=>button.addEventListener('click',()=>{size=Number(button.dataset.size);document.querySelectorAll('[data-size]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});renderProducts()}));renderProducts();
